// 1. Get the current time in GMT+8
const now = new Date();
const gmt8Offset = 8 * 60 * 60 * 1000; // 8 hours in milliseconds
const  refresh_seconds =$input.first().json.refresh_seconds
const  from_date=$input.first().json.from_date
// 2. Parse input data from the previous node
const fromDateStr = from_date; 
const refreshSeconds = parseInt(refresh_seconds, 10) || 3600;
const fromDate = new Date(fromDateStr);

// 3. Validation: If current time is before from_date, stop execution
if (now < fromDate) {
  return []; // Returning an empty array stops the workflow here if "Always Output Data" is off
}

// 4. Align the intervals properly
// Find out how many intervals have passed between from_date and now
const elapsedMs = now.getTime() - fromDate.getTime();
const intervalMs = refreshSeconds * 1000;

// Calculate the number of full intervals passed, then find the very next slot
const completedIntervals = Math.floor(elapsedMs / intervalMs);
let nextSlotTimeMs = fromDate.getTime() + ((completedIntervals + 1) * intervalMs);

// 5. Generate the next 100 slots
const timeslots = [];
for (let i = 0; i < 100; i++) {
  const slotDate = new Date(nextSlotTimeMs + (i * intervalMs));

  // Convert to local GMT+8 ISO string for clean output display
  const gmt8Time = new Date(slotDate.getTime() + gmt8Offset);
  const gmt8String = gmt8Time.toISOString().replace('Z', '+08:00');

  timeslots.push({
    slot_index: i + 1,
    timestamp_utc: slotDate.toISOString(),
    timestamp_gmt8: gmt8String
  });
}

// 6. Return the array of timeslots to n8n
return timeslots.map(slot => ({ json: slot }));
