console.log("=== STARTING TIMESLOT CHECK ===");
console.log("Current GMT+8 Time String:", nowGmt8Str);
console.log("Current GMT+8 Time (MS):", nowGmt8Ms);

// 2. Define your window configuration (5 minutes in milliseconds)
const FIVE_MINUTES_MS = 30 * 60 * 1000;
const totalItems = $input.all().length;
console.log(`Total timeslots received to check: ${totalItems}`);

let checkedCount = 0;

// 3. Loop through all incoming timeslot items to find a match
for (const item of $input.all()) {
