  if (!slotGmt8Str) {
    console.log(`[Slot ${checkedCount}/${totalItems}] Skipped: Missing timestamp_gmt8 property.`);
    continue;
  }

  // Convert the slot string into an absolute millisecond timestamp
  const slotMs = new Date(slotGmt8Str).getTime();
  const timeDifference = slotMs - nowGmt8Ms;
  const diffInMinutes = (timeDifference / 1000 / 60).toFixed(2);

  // LOG EVERY SLOT ENCOUNTERED FOR VISIBILITY
  console.log(`[Slot ${checkedCount}/${totalItems}] Checking: ${slotGmt8Str} | Diff: ${diffInMinutes} mins`);

  // 4. Check if the current time is within 5 minutes BEFORE the target slot time
  if (timeDifference >= 0 && timeDifference <= FIVE_MINUTES_MS) {
    console.log(`🎯 MATCH FOUND at slot ${checkedCount}! Executing Postgres trigger node.`);

    return [{
      json: {
        match_found: true,
        matched_slot_gmt8: slotGmt8Str,
        current_time_gmt8: nowGmt8Str,
        minutes_remaining: diffInMinutes
      }
