const storage = $('Code - prepare storage & decrypt1').first().json;
const item = $input.first();

if (!item.binary?.data) {
  return [{ json: { skipped: true, reason: 'No audio binary — download may have failed or message is not audio' } }];
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');

const mime = (storage.mime_type ?? '').toLowerCase();
const formatMap = [
  ['ogg', 'ogg'],
  ['opus', 'ogg'],
  ['mpeg', 'mp3'],
  ['mp3', 'mp3'],
  ['m4a', 'm4a'],
  ['mp4', 'm4a'],
  ['wav', 'wav'],
  ['webm', 'webm'],
  ['aac', 'aac'],
  ['flac', 'flac'],
];

let format = 'ogg';
for (const [needle, fmt] of formatMap) {
  if (mime.includes(needle)) {
    format = fmt;
    break;
  }
}

return [{
  json: {
    message_id: storage.message_id,
    owner_email: storage.owner_email,
    owner_phone_num: storage.owner_phone_num,
    media_kind: storage.media_kind,
    chirp_body: {
      model: 'google/chirp-3',
      input_audio: {
        data: base64,
        format,
      },
    },
  },
}];

const prep = $('Code - prepare Chirp 3 base64').first().json;
const res = $input.first().json;

const text =
  res.text ??
  res.transcript ??
  res.data?.text ??
  res.choices?.[0]?.message?.content ??
  '';

if (!text) {
  return [{ json: { skipped: true, reason: 'Chirp 3 returned no text', raw: res } }];
}

return [{
  json: {
    message_id: prep.message_id,
    owner_email: prep.owner_email,
    owner_phone_num: prep.owner_phone_num,
    transcript: String(text).trim(),
    model_name: 'google/chirp-3',
  },
}];

const OWNER_EMAIL = 'hello@actionnow.my';
const OWNER_PHONE = '+60103364933';

const input = $input.first().json;
const body = input.body ?? input;
const event = body.event;
const messages = body.data?.messages;

if (!messages) {
  throw new Error('Missing data.messages in webhook payload');
}

const key = messages.key ?? {};
const keyId = String(key.id ?? messages.id ?? '').trim();
if (!keyId) {
  throw new Error('Missing WhatsApp message id (key.id and messages.id both empty)');
}
// WASender may send id in both places; prefer key.id without failing the workflow
const altId = messages.id != null ? String(messages.id).trim() : '';
const canonicalMessageId = String(key.id ?? altId).trim() || keyId;

function unwrapMediaMessage(message) {
  if (!message || typeof message !== 'object') return {};
  if (message.ephemeralMessage?.message) return unwrapMediaMessage(message.ephemeralMessage.message);
  if (message.viewOnceMessage?.message) return unwrapMediaMessage(message.viewOnceMessage.message);
  if (message.viewOnceMessageV2?.message) return unwrapMediaMessage(message.viewOnceMessageV2.message);
  if (message.documentWithCaptionMessage?.message) return unwrapMediaMessage(message.documentWithCaptionMessage.message);
  if (message.imageWithCaptionMessage?.message) return unwrapMediaMessage(message.imageWithCaptionMessage.message);
  return message;
}

function normalizeMediaKey(mediaKey) {
  if (mediaKey == null) return null;
  if (typeof mediaKey === 'string') return mediaKey;
  if (typeof mediaKey === 'object' && mediaKey.type === 'Buffer' && Array.isArray(mediaKey.data)) {
    return Buffer.from(mediaKey.data).toString('base64');
  }
  if (Array.isArray(mediaKey)) return Buffer.from(mediaKey).toString('base64');
  return String(mediaKey);
}

const DECRYPT_MESSAGE_KEY = {
  pttMessage: 'audioMessage',
  audioMessage: 'audioMessage',
  imageMessage: 'imageMessage',
  videoMessage: 'videoMessage',
  documentMessage: 'documentMessage',
  stickerMessage: 'stickerMessage',
};

function buildDecryptMediaBlock(details) {
  const keep = [
    'url', 'mimetype', 'mediaKey', 'fileSha256', 'fileLength', 'fileName',
    'directPath', 'mediaKeyTimestamp', 'caption', 'height', 'width', 'seconds', 'ptt',
  ];
  const out = {};
  for (const k of keep) {
    if (details[k] != null && details[k] !== '') out[k] = details[k];
  }
  if (out.mediaKey != null) out.mediaKey = normalizeMediaKey(out.mediaKey);
  return out;
}

const msg = unwrapMediaMessage(messages.message ?? {});
const isGroup =
  event === 'messages-group.received' ||
  String(key.remoteJid || '').endsWith('@g.us');

const MEDIA_MAP = [
  ['imageMessage', 'image'],
  ['videoMessage', 'video'],
  ['audioMessage', 'audio'],
  ['pttMessage', 'audio'],
  ['documentMessage', 'document'],
  ['stickerMessage', 'sticker'],
];

let contentType = 'text';
let mediaKind = 'text';
let mediaDetails = null;
let messageKey = null;

for (const [k, kind] of MEDIA_MAP) {
  if (msg[k]) {
    messageKey = k;
    contentType = kind;
    mediaKind = kind;
    mediaDetails = msg[k];
    break;
  }
}

const hasMedia = Boolean(mediaDetails);

function normalizeText(v) {
  if (v == null) return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function mediaFingerprint(details, kind) {
  if (!details) return null;
  const parts = [
    kind,
    normalizeMediaKey(details.mediaKey) ?? '',
    details.url ?? '',
    details.fileLength != null ? String(details.fileLength) : '',
    details.fileSha256 ?? '',
  ].filter(Boolean);
  if (!parts.length) return null;
  const raw = parts.join('|');
  let hash = 0;
  for (let i = 0; i < raw.length; i++) {
    hash = ((hash << 5) - hash + raw.charCodeAt(i)) | 0;
  }
  return Math.abs(hash).toString(36).padStart(8, '0').slice(0, 8);
}

const contentFingerprint = hasMedia ? mediaFingerprint(mediaDetails, mediaKind) : null;

let whatsappTimestamp = messages.messageTimestamp ?? null;
if (whatsappTimestamp == null && body.timestamp != null) {
  const t = Number(body.timestamp);
  whatsappTimestamp = t > 1e12 ? Math.floor(t / 1000) : t;
}

const messageBody =
  normalizeText(messages.messageBody) ??
  normalizeText(mediaDetails?.caption) ??
  null;

const record = {
  owner_email: OWNER_EMAIL,
  owner_phone_num: OWNER_PHONE,
  event_type: event,
  whatsapp_timestamp: whatsappTimestamp,
  message_id: canonicalMessageId,
  from_me: Boolean(key.fromMe),
  chat_jid: key.remoteJid,
  is_group: isGroup,
  addressing_mode: key.addressingMode ?? null,
  sender_pn: isGroup ? null : (key.senderPn ?? null),
  cleaned_sender_pn: isGroup ? null : (key.cleanedSenderPn ?? null),
  sender_lid: isGroup ? null : (key.senderLid ?? null),
  participant: isGroup ? (key.participant ?? null) : null,
  participant_pn: isGroup ? (key.participantPn ?? null) : null,
  cleaned_participant_pn: isGroup ? (key.cleanedParticipantPn ?? null) : null,
  participant_lid: isGroup ? (key.participantLid ?? null) : null,
  sender_phone: key.cleanedParticipantPn ?? key.cleanedSenderPn ?? null,
  sender_lid_resolved: key.participantLid ?? key.participant ?? key.senderLid ?? null,
  message_body: messageBody,
  content_type: contentType,
  content_fingerprint: contentFingerprint,
  raw_payload: body,
  has_media: hasMedia,
  media_processing_status: hasMedia ? 'pending' : 'none',
};

let media_row = null;
let decrypt_request = null;

if (hasMedia && messageKey) {
  media_row = {
    owner_email: OWNER_EMAIL,
    owner_phone_num: OWNER_PHONE,
    message_id: canonicalMessageId,
    media_kind: mediaKind,
    mime_type: mediaDetails.mimetype ?? null,
    file_name: mediaDetails.fileName ?? null,
    file_size: mediaDetails.fileLength != null ? Number(mediaDetails.fileLength) : null,
    caption: normalizeText(mediaDetails.caption) ?? normalizeText(messages.messageBody),
    encrypted_url: mediaDetails.url ?? null,
    media_key: normalizeMediaKey(mediaDetails.mediaKey),
    decrypt_status: 'pending',
  };

  const decryptMessageKey = DECRYPT_MESSAGE_KEY[messageKey] ?? messageKey;
  const mediaBlock = buildDecryptMediaBlock(mediaDetails);

  if (!mediaBlock.url || !mediaBlock.mediaKey) {
    throw new Error(`Media missing url or mediaKey for ${messageKey}`);
  }

  decrypt_request = {
    data: {
      messages: {
        key: {
          id: canonicalMessageId,
          remoteJid: key.remoteJid ?? undefined,
          participant: key.participant ?? undefined,
        },
        message: { [decryptMessageKey]: mediaBlock },
      },
    },
  };

  if (body.sessionId) decrypt_request.sessionId = body.sessionId;
}

return [{ json: { ...record, media_row, decrypt_request } }];

const parsed = $('Code - parse message & media type2').first().json;
const media = parsed.media_row;
const decrypt = $input.first().json;
const publicUrl = decrypt.publicUrl ?? decrypt.data?.publicUrl ?? null;
const decryptError =
  decrypt.error ??
  (decrypt.success === false ? (decrypt.message ?? JSON.stringify(decrypt)) : null);

const extMap = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'audio/ogg; codecs=opus': 'ogg',
  'audio/ogg': 'ogg',
  'audio/mpeg': 'mp3',
  'audio/mp4': 'm4a',
  'video/mp4': 'mp4',
  'application/pdf': 'pdf',
};

const mime = media?.mime_type ?? 'application/octet-stream';
const extFromName = media?.file_name?.includes('.') ? media.file_name.split('.').pop() : null;
const ext = extMap[mime] ?? extFromName ?? 'bin';
const phone = String(parsed.owner_phone_num ?? 'unknown').replace(/\D/g, '');
const d = new Date();

// message_id from WhatsApp + media fingerprint (unique per attachment, even with empty caption)
const tag = parsed.content_fingerprint ?? parsed.message_id.slice(-8);
const storage_path = `${phone}/${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, '0')}/${parsed.message_id}_${tag}.${ext}`;

const interpretationMap = {
  audio: ['transcript'],
  video: ['video_transcript'],
  image: ['caption', 'ocr'],
  document: ['document_text'],
  sticker: ['caption'],
};

return [{
  json: {
    message_id: parsed.message_id,
    public_url: publicUrl,
    decrypt_error: decryptError,
    storage_path,
    storage_bucket: 'action-now',
    mime_type: mime,
    media_kind: parsed.content_type,
    content_fingerprint: parsed.content_fingerprint,
    owner_email: parsed.owner_email,
    owner_phone_num: parsed.owner_phone_num,
    interpretation_types: interpretationMap[parsed.content_type] ?? [],
  },
}];

const storage = $('Code - prepare storage & decrypt1').first().json;
const mediaRow = $('Postgres - upsert whatsapp_message_media1').first().json;
const mediaId = mediaRow?.id;

if (!mediaId) {
  return [];
}

const types = storage.interpretation_types ?? [];

return types.map((interpretation_type) => ({
  json: {
    media_id: mediaId,
    message_id: storage.message_id,
    owner_email: storage.owner_email,
    owner_phone_num: storage.owner_phone_num,
    interpretation_type,
    status: 'pending',
    media_kind: storage.media_kind,
    storage_path: storage.storage_path,
  },
}));

